+export type Counter = {
+  value: number
+  increment: () => number
+  reset: () => number
+}
+
+export function createCounter(initial = 0): Counter {
+  let value = initial
+
+  return {
+    get value() {
+      return value
+    },
+    increment() {
+      value += 1
+      return value
+    },
+    reset() {
+      value = 0
+      return value
+    },
+  }
+}
