+import assert from 'node:assert/strict';
+import { spawn } from 'node:child_process';
+import { existsSync, readFileSync, statSync } from 'node:fs';
+import http from 'node:http';
+import { test } from 'node:test';
+import { fileURLToPath } from 'node:url';
+import path from 'node:path';
+import vm from 'node:vm';
+
+const __dirname = path.dirname(fileURLToPath(import.meta.url));
+const rootDir = path.resolve(__dirname, '..');
+const host = '127.0.0.1';
+const requestedPort = String(41000 + Math.floor(Math.random() * 1000));
+
+test('click counter page is accessible and works end-to-end', async (t) => {
+  const app = await bootDeliveredApp();
+  t.after(async () => {
+    await app.close();
+  });
+
+  const response = await request(app.origin, '/');
+  assert.equal(response.statusCode, 200, `GET / must return 200, got ${response.statusCode}`);
+  assert.match(response.headers['content-type'] ?? 'text/html', /html/i, 'GET / must serve an HTML page');
+
+  const page = await loadPage(response.body, app.origin);
+  const buttons = page.document.querySelectorAll('button');
+  assert.ok(buttons.length >= 2, 'page must expose at least an increment button and a reset button');
+
+  const resetButton = buttons.find((button) => /reset/i.test(accessibleName(button)));
+  assert.ok(resetButton, 'reset control must be a real <button> with an accessible name containing "reset"');
+
+  const incrementCandidates = buttons.filter((button) => button !== resetButton);
+  assert.ok(incrementCandidates.length > 0, 'page must expose a separate increment button');
+
+  const incrementButton =
+    incrementCandidates.find((button) => /(click|increment|add|\+|count)/i.test(accessibleName(button))) ??
+    incrementCandidates[0];
+
+  const initialNumbers = visibleIntegers(page.document);
+  assert.ok(initialNumbers.length > 0, 'page must visibly show the current counter number');
+
+  await clickAndSettle(incrementButton);
+  const afterOneClick = visibleIntegers(page.document);
+  await clickAndSettle(incrementButton);
+  const afterTwoClicks = visibleIntegers(page.document);
+
+  const observedInitialCount = initialNumbers.find(
+    (number) => afterOneClick.includes(number + 1) && afterTwoClicks.includes(number + 2),
+  );
+  assert.notEqual(
+    observedInitialCount,
+    undefined,
+    `clicking the increment button twice must visibly increase the counter by 1 each time; saw ${JSON.stringify({
+      initialNumbers,
+      afterOneClick,
+      afterTwoClicks,
+    })}`,
+  );
+
+  await clickAndSettle(resetButton);
+  const afterReset = visibleIntegers(page.document);
+  assert.ok(afterReset.includes(0), `clicking reset must visibly return the counter to 0; saw ${afterReset.join(', ')}`);
+});
+
+async function bootDeliveredApp() {
+  const directEntries = discoverDirectEntries();
+  const errors = [];
+
+  for (const entry of directEntries) {
+    try {
+      const child = spawn(process.execPath, [entry], {
+        cwd: rootDir,
+        env: { ...process.env, HOST: host, PORT: requestedPort, NODE_ENV: 'test' },
+        stdio: ['ignore', 'pipe', 'pipe'],
+        windowsHide: true,
+      });
+      const result = await waitForServer(child, requestedPort);
+      if (result.ready) {
+        return {
+          origin: result.origin,
+          close: () => stopChild(child),
+        };
+      }
+      errors.push(`${path.relative(rootDir, entry)} did not start an HTTP server: ${result.reason}`);
+      await stopChild(child);
+    } catch (error) {
+      errors.push(`${path.relative(rootDir, entry)} failed to launch: ${error.message}`);
+    }
+  }
+
+  const npmCommand = discoverNpmCommand();
+  if (npmCommand) {
+    const child = spawn(npmCommand.command, npmCommand.args, {
+      cwd: rootDir,
+      env: { ...process.env, HOST: host, PORT: requestedPort, NODE_ENV: 'test' },
+      stdio: ['ignore', 'pipe', 'pipe'],
+      shell: process.platform === 'win32',
+      windowsHide: true,
+    });
+    const result = await waitForServer(child, requestedPort);
+    if (result.ready) {
+      return {
+        origin: result.origin,
+        close: () => stopChild(child),
+      };
+    }
+    errors.push(`${npmCommand.command} ${npmCommand.args.join(' ')} did not start an HTTP server: ${result.reason}`);
+    await stopChild(child);
+  }
+
+  const staticRoot = discoverStaticRoot();
+  if (staticRoot) {
+    const server = await startStaticServer(staticRoot);
+    return {
+      origin: `http://${host}:${server.address().port}`,
+      close: () => new Promise((resolve) => server.close(resolve)),
+    };
+  }
+
+  assert.fail(
+    `Could not discover how to boot the delivered web page. Tried direct Node entries and npm scripts. Details: ${errors.join(
+      '; ',
+    )}`,
+  );
+}
+
+function discoverDirectEntries() {
+  const candidates = [];
+  const packageJson = readPackageJson();
+
+  if (packageJson?.main) {
+    candidates.push(packageJson.main);
+  }
+
+  if (typeof packageJson?.bin === 'string') {
+    candidates.push(packageJson.bin);
+  } else if (packageJson?.bin && typeof packageJson.bin === 'object') {
+    candidates.push(...Object.values(packageJson.bin));
+  }
+
+  candidates.push(
+    'server.mjs',
+    'server.js',
+    'server.cjs',
+    'index.mjs',
+    'index.js',
+    'index.cjs',
+    'app.mjs',
+    'app.js',
+    'src/server.mjs',
+    'src/server.js',
+    'src/index.mjs',
+    'src/index.js',
+    'dist/server.mjs',
+    'dist/server.js',
+    'dist/index.mjs',
+    'dist/index.js',
+    'build/server.js',
+    'build/index.js',
+  );
+
+  return [...new Set(candidates)]
+    .filter(Boolean)
+    .map((candidate) => path.resolve(rootDir, candidate))
+    .filter((candidate) => existsSync(candidate) && statSync(candidate).isFile());
+}
+
+function discoverNpmCommand() {
+  const packageJson = readPackageJson();
+  const scripts = packageJson?.scripts ?? {};
+  for (const name of ['start', 'serve', 'dev']) {
+    if (scripts[name]) {
+      return { command: 'npm', args: ['run', name, '--silent'] };
+    }
+  }
+  return null;
+}
+
+function discoverStaticRoot() {
+  for (const candidate of ['.', 'public', 'dist', 'build']) {
+    const absolute = path.resolve(rootDir, candidate);
+    if (existsSync(path.join(absolute, 'index.html'))) {
+      return absolute;
+    }
+  }
+  return null;
+}
+
+function readPackageJson() {
+  const packagePath = path.join(rootDir, 'package.json');
+  if (!existsSync(packagePath)) {
+    return null;
+  }
+  return JSON.parse(readFileSync(packagePath, 'utf8'));
+}
+
+async function waitForServer(child, port) {
+  let output = '';
+  child.stdout.on('data', (data) => {
+    output += data.toString();
+  });
+  child.stderr.on('data', (data) => {
+    output += data.toString();
+  });
+
+  const deadline = Date.now() + 8_000;
+  let exitCode = null;
+  child.once('exit', (code) => {
+    exitCode = code;
+  });
+
+  while (Date.now() < deadline) {
+    if (exitCode !== null) {
+      return { ready: false, reason: `process exited with code ${exitCode}; output: ${output.trim()}` };
+    }
+
+    const printedOrigin = output.match(/https?:\/\/(?:localhost|127\.0\.0\.1|\[::1\])(?::\d+)?/i)?.[0];
+    for (const origin of [`http://${host}:${port}`, printedOrigin].filter(Boolean)) {
+      try {
+        const response = await request(origin, '/');
+        if (response.statusCode > 0) {
+          return { ready: true, origin };
+        }
+      } catch {
+        // Keep waiting until the child process either exits or starts responding.
+      }
+    }
+
+    await delay(150);
+  }
+
+  return { ready: false, reason: `timed out waiting on PORT=${port}; output: ${output.trim()}` };
+}
+
+function startStaticServer(staticRoot) {
+  const server = http.createServer((req, res) => {
+    const url = new URL(req.url ?? '/', `http://${host}`);
+    const requested = decodeURIComponent(url.pathname === '/' ? '/index.html' : url.pathname);
+    const filePath = path.resolve(staticRoot, `.${requested}`);
+
+    if (!filePath.startsWith(staticRoot) || !existsSync(filePath) || !statSync(filePath).isFile()) {
+      res.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' });
+      res.end('Not found');
+      return;
+    }
+
+    res.writeHead(200, { 'content-type': contentType(filePath) });
+    res.end(readFileSync(filePath));
+  });
+
+  return new Promise((resolve, reject) => {
+    server.once('error', reject);
+    server.listen(0, host, () => resolve(server));
+  });
+}
+
+function request(origin, requestPath) {
+  return new Promise((resolve, reject) => {
+    const url = new URL(requestPath, origin);
+    const req = http.get(url, (res) => {
+      const chunks = [];
+      res.on('data', (chunk) => chunks.push(chunk));
+      res.on('end', () => {
+        resolve({
+          statusCode: res.statusCode ?? 0,
+          headers: res.headers,
+          body: Buffer.concat(chunks).toString('utf8'),
+        });
+      });
+    });
+    req.setTimeout(4_000, () => req.destroy(new Error(`Timed out requesting ${url.href}`)));
+    req.on('error', reject);
+  });
+}
+
+async function loadPage(html, origin) {
+  const document = parseHtml(html);
+  const window = createWindow(document, origin);
+  document.defaultView = window;
+
+  const context = vm.createContext(window);
+  for (const script of extractScripts(html)) {
+    if (script.type && !/^(module|text\/javascript|application\/javascript)$/i.test(script.type)) {
+      continue;
+    }
+
+    let source = script.content;
+    if (script.src) {
+      const response = await request(origin, script.src);
+      assert.equal(response.statusCode, 200, `script ${script.src} must load successfully`);
+      source = response.body;
+    }
+
+    assert.doesNotMatch(
+      source,
+      /^\s*import\s|^\s*export\s/m,
+      'acceptance probe can execute dependency-free browser scripts; bundled pages must not require unresolved module imports at runtime',
+    );
+    vm.runInContext(source, context, { filename: script.src || 'inline-script.js', timeout: 2_000 });
+  }
+
+  document.readyState = 'interactive';
+  document.dispatchEvent(new window.Event('DOMContentLoaded', { bubbles: false }));
+  document.readyState = 'complete';
+  window.dispatchEvent(new window.Event('load', { bubbles: false }));
+  await delay(50);
+
+  return { window, document };
+}
+
+function createWindow(document, origin) {
+  class Event {
+    constructor(type, options = {}) {
+      this.type = type;
+      this.bubbles = Boolean(options.bubbles);
+      this.cancelable = Boolean(options.cancelable);
+      this.defaultPrevented = false;
+      this.target = null;
+      this.currentTarget = null;
+    }
+
+    preventDefault() {
+      if (this.cancelable) {
+        this.defaultPrevented = true;
+      }
+    }
+  }
+
+  class MouseEvent extends Event {}
+  const localStorage = new Map();
+  const location = new URL(origin);
+  const window = {
+    document,
+    Event,
+    MouseEvent,
+    HTMLElement: ElementNode,
+    Node: BaseNode,
+    console,
+    location,
+    navigator: { userAgent: 'node-acceptance-probe' },
+    localStorage: {
+      getItem: (key) => (localStorage.has(String(key)) ? localStorage.get(String(key)) : null),
+      setItem: (key, value) => localStorage.set(String(key), String(value)),
+      removeItem: (key) => localStorage.delete(String(key)),
+      clear: () => localStorage.clear(),
+    },
+    setTimeout,
+    clearTimeout,
+    setInterval,
+    clearInterval,
+  };
+  window.window = window;
+  window.self = window;
+  window.globalThis = window;
+  Object.setPrototypeOf(document, eventTargetPrototype);
+  Object.setPrototypeOf(window, eventTargetPrototype);
+  return window;
+}
+
+function parseHtml(html) {
+  const document = new DocumentNode();
+  const stack = [document];
+  const tokenPattern = /<!--[\s\S]*?-->|<!doctype[^>]*>|<\/?[a-zA-Z][^>]*>|[^<]+/gi;
+  let match;
+
+  while ((match = tokenPattern.exec(html))) {
+    const token = match[0];
+    if (token.startsWith('<!--') || /^<!doctype/i.test(token)) {
+      continue;
+    }
