test('click counter page is accessible and works end-to-end', async (t) => {
  const app = await bootDeliveredApp();
  t.after(async () => {
    await app.close();
  });

  const response = await request(app.origin, '/');
  assert.equal(response.statusCode, 200, `GET / must return 200, got ${response.statusCode}`);
  assert.match(response.headers['content-type'] ?? 'text/html', /html/i, 'GET / must serve an HTML page');

  const page = await loadPage(response.body, app.origin);
  const buttons = page.document.querySelectorAll('button');
  assert.ok(buttons.length >= 2, 'page must expose at least an increment button and a reset button');

  const resetButton = buttons.find((button) => /reset/i.test(accessibleName(button)));
  assert.ok(resetButton, 'reset control must be a real <button> with an accessible name containing "reset"');

  const incrementCandidates = buttons.filter((button) => button !== resetButton);
  assert.ok(incrementCandidates.length > 0, 'page must expose a separate increment button');

  const incrementButton =
    incrementCandidates.find((button) => /(click|increment|add|\+|count)/i.test(accessibleName(button))) ??
    incrementCandidates[0];

  const initialNumbers = visibleIntegers(page.document);
  assert.ok(initialNumbers.length > 0, 'page must visibly show the current counter number');

  await clickAndSettle(incrementButton);
  const afterOneClick = visibleIntegers(page.document);
  await clickAndSettle(incrementButton);
  const afterTwoClicks = visibleIntegers(page.document);

  const observedInitialCount = initialNumbers.find(
    (number) => afterOneClick.includes(number + 1) && afterTwoClicks.includes(number + 2),
  );
  assert.notEqual(
    observedInitialCount,
    undefined,
    `clicking the increment button twice must visibly increase the counter by 1 each time; saw ${JSON.stringify({
      initialNumbers,
      afterOneClick,
      afterTwoClicks,
    })}`,
  );

  await clickAndSettle(resetButton);
  const afterReset = visibleIntegers(page.document);
  assert.ok(afterReset.includes(0), `clicking reset must visibly return the counter to 0; saw ${afterReset.join(', ')}`);
});

