+    'server.js',
+    'server.cjs',
+    'index.mjs',
+    'index.js',
+    'index.cjs',
+    'app.mjs',
+    'app.js',
+    'src/server.mjs',
+    'src/server.js',
+    'src/index.mjs',
+    'src/index.js',
+    'dist/server.mjs',
+    'dist/server.js',
+    'dist/index.mjs',
+    'dist/index.js',
+    'build/server.js',
+    'build/index.js',
